140	  public static void applyTrimPathIfNeeded(
141	      Path path, float startValue, float endValue, float offsetValue) {
142	    if (L.isTraceEnabled()) {
143	      L.beginSection("applyTrimPathIfNeeded");
144	    }
145	    final PathMeasure pathMeasure = threadLocalPathMeasure.get();
146	    final Path tempPath = threadLocalTempPath.get();
147	    final Path tempPath2 = threadLocalTempPath2.get();
148	
149	    pathMeasure.setPath(path, false);
150	
151	    float length = pathMeasure.getLength();
152	    if (startValue == 1f && endValue == 0f) {
153	      if (L.isTraceEnabled()) {
154	        L.endSection("applyTrimPathIfNeeded");
155	      }
156	      return;
157	    }
158	    if (length < 1f || Math.abs(endValue - startValue - 1) < .01) {
159	      if (L.isTraceEnabled()) {
160	        L.endSection("applyTrimPathIfNeeded");
161	      }
162	      return;
163	    }
164	    float start = length * startValue;
165	    float end = length * endValue;
166	    float newStart = Math.min(start, end);
167	    float newEnd = Math.max(start, end);
168	
169	    float offset = offsetValue * length;
170	    newStart += offset;
171	    newEnd += offset;
172	
173	    // If the trim path has rotated around the path, we need to shift it back.
174	    if (newStart >= length && newEnd >= length) {
175	      newStart = MiscUtils.floorMod(newStart, length);
176	      newEnd = MiscUtils.floorMod(newEnd, length);
177	    }
178	
179	    if (newStart < 0) {
180	      newStart = MiscUtils.floorMod(newStart, length);
181	    }
182	    if (newEnd < 0) {
183	      newEnd = MiscUtils.floorMod(newEnd, length);
184	    }
185	
186	    // If the start and end are equals, return an empty path.
187	    if (newStart == newEnd) {
188	      path.reset();
189	      if (L.isTraceEnabled()) {
190	        L.endSection("applyTrimPathIfNeeded");
191	      }
192	      return;
193	    }
194	
195	    if (newStart >= newEnd) {
196	      newStart -= length;
197	    }
198	
199	    tempPath.reset();
200	    pathMeasure.getSegment(
201	        newStart,
202	        newEnd,
203	        tempPath,
204	        true);
205	
206	    if (newEnd > length) {
207	      tempPath2.reset();
208	      pathMeasure.getSegment(
209	          0,
210	          newEnd % length,
211	          tempPath2,
212	          true);
213	      tempPath.addPath(tempPath2);
214	    } else if (newStart < 0) {
215	      tempPath2.reset();
216	      pathMeasure.getSegment(
217	          length + newStart,
218	          length,
219	          tempPath2,
220	          true);
221	      tempPath.addPath(tempPath2);
222	    }
223	    path.set(tempPath);
224	    if (L.isTraceEnabled()) {
225	      L.endSection("applyTrimPathIfNeeded");
226	    }
227	  }
