225	  private void applyTrimPath(Canvas canvas, PathGroup pathGroup) {
226	    if (L.isTraceEnabled()) {
227	      L.beginSection("StrokeContent#applyTrimPath");
228	    }
229	    if (pathGroup.trimPath == null) {
230	      if (L.isTraceEnabled()) {
231	        L.endSection("StrokeContent#applyTrimPath");
232	      }
233	      return;
234	    }
235	    path.reset();
236	    for (int j = pathGroup.paths.size() - 1; j >= 0; j--) {
237	      path.addPath(pathGroup.paths.get(j).getPath());
238	    }
239	    float animStartValue = pathGroup.trimPath.getStart().getValue() / 100f;
240	    float animEndValue = pathGroup.trimPath.getEnd().getValue() / 100f;
241	    float animOffsetValue = pathGroup.trimPath.getOffset().getValue() / 360f;
242	
243	    // If the start-end is ~100, consider it to be the full path.
244	    if (animStartValue < 0.01f && animEndValue > 0.99f) {
245	      canvas.drawPath(path, paint);
246	      if (L.isTraceEnabled()) {
247	        L.endSection("StrokeContent#applyTrimPath");
248	      }
249	      return;
250	    }
251	
252	    pm.setPath(path, false);
253	    float totalLength = pm.getLength();
254	    while (pm.nextContour()) {
255	      totalLength += pm.getLength();
256	    }
257	    float offsetLength = totalLength * animOffsetValue;
258	    float startLength = totalLength * animStartValue + offsetLength;
259	    float endLength = Math.min(totalLength * animEndValue + offsetLength, startLength + totalLength - 1f);
260	
261	    float currentLength = 0;
262	    for (int j = pathGroup.paths.size() - 1; j >= 0; j--) {
263	      trimPathPath.set(pathGroup.paths.get(j).getPath());
264	      pm.setPath(trimPathPath, false);
265	      float length = pm.getLength();
266	      if (endLength > totalLength && endLength - totalLength < currentLength + length &&
267	          currentLength < endLength - totalLength) {
268	        // Draw the segment when the end is greater than the length which wraps around to the
269	        // beginning.
270	        float startValue;
271	        if (startLength > totalLength) {
272	          startValue = (startLength - totalLength) / length;
273	        } else {
274	          startValue = 0;
275	        }
276	        float endValue = Math.min((endLength - totalLength) / length, 1);
277	        Utils.applyTrimPathIfNeeded(trimPathPath, startValue, endValue, 0);
278	        canvas.drawPath(trimPathPath, paint);
279	      } else
280	        //noinspection StatementWithEmptyBody
281	        if (currentLength + length < startLength || currentLength > endLength) {
282	          // Do nothing
283	        } else if (currentLength + length <= endLength && startLength < currentLength) {
284	          canvas.drawPath(trimPathPath, paint);
285	        } else {
286	          float startValue;
287	          if (startLength < currentLength) {
288	            startValue = 0;
289	          } else {
290	            startValue = (startLength - currentLength) / length;
291	          }
292	          float endValue;
293	          if (endLength > currentLength + length) {
294	            endValue = 1f;
295	          } else {
296	            endValue = (endLength - currentLength) / length;
297	          }
298	          Utils.applyTrimPathIfNeeded(trimPathPath, startValue, endValue, 0);
299	          canvas.drawPath(trimPathPath, paint);
300	        }
301	      currentLength += length;
302	    }
303	    if (L.isTraceEnabled()) {
304	      L.endSection("StrokeContent#applyTrimPath");
305	    }
306	  }
