312	    path.reset();
313	    for (int i = 0; i < pathGroups.size(); i++) {
314	      PathGroup pathGroup = pathGroups.get(i);
315	      for (int j = 0; j < pathGroup.paths.size(); j++) {
316	        path.addPath(pathGroup.paths.get(j).getPath(), parentMatrix);
317	      }
318	    }
319	    path.computeBounds(rect, false);
320	
321	    float width = ((FloatKeyframeAnimation) widthAnimation).getFloatValue();
322	    rect.set(rect.left - width / 2f, rect.top - width / 2f,
323	        rect.right + width / 2f, rect.bottom + width / 2f);
324	    outBounds.set(rect);
325	    // Add padding to account for rounding errors.
326	    outBounds.set(
327	        outBounds.left - 1,
328	        outBounds.top - 1,
329	        outBounds.right + 1,
330	        outBounds.bottom + 1
331	    );
332	    if (L.isTraceEnabled()) {
333	      L.endSection("StrokeContent#getBounds");
334	    }
335	  }
