337	  private void applyDashPatternIfNeeded() {
338	    if (L.isTraceEnabled()) {
339	      L.beginSection("StrokeContent#applyDashPattern");
340	    }
341	    if (dashPatternAnimations.isEmpty()) {
342	      if (L.isTraceEnabled()) {
343	        L.endSection("StrokeContent#applyDashPattern");
344	      }
345	      return;
346	    }
347	
348	    for (int i = 0; i < dashPatternAnimations.size(); i++) {
349	      dashPatternValues[i] = dashPatternAnimations.get(i).getValue();
350	      // If the value of the dash pattern or gap is too small, the number of individual sections
351	      // approaches infinity as the value approaches 0.
352	      // To mitigate this, we essentially put a minimum value on the dash pattern size of 1px
353	      // and a minimum gap size of 0.01.
354	      if (i % 2 == 0) {
355	        if (dashPatternValues[i] < 1f) {
356	          dashPatternValues[i] = 1f;
357	        }
358	      } else {
359	        if (dashPatternValues[i] < 0.1f) {
360	          dashPatternValues[i] = 0.1f;
361	        }
362	      }
363	    }
364	    float offset = dashPatternOffsetAnimation == null ? 0f : dashPatternOffsetAnimation.getValue();
365	    paint.setPathEffect(new DashPathEffect(dashPatternValues, offset));
366	    if (L.isTraceEnabled()) {
367	      L.endSection("StrokeContent#applyDashPattern");
368	    }
369	  }
