379	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
380	    if (property == LottieProperty.OPACITY) {
381	      opacityAnimation.setValueCallback((LottieValueCallback<Integer>) callback);
382	    } else if (property == LottieProperty.STROKE_WIDTH) {
383	      widthAnimation.setValueCallback((LottieValueCallback<Float>) callback);
384	    } else if (property == LottieProperty.COLOR_FILTER) {
385	      if (colorFilterAnimation != null) {
386	        layer.removeAnimation(colorFilterAnimation);
387	      }
388	
389	      if (callback == null) {
390	        colorFilterAnimation = null;
391	      } else {
392	        colorFilterAnimation =
393	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<ColorFilter>) callback);
394	        colorFilterAnimation.addUpdateListener(this);
395	        layer.addAnimation(colorFilterAnimation);
396	      }
397	    } else if (property == LottieProperty.BLUR_RADIUS) {
398	      if (blurAnimation != null) {
399	        blurAnimation.setValueCallback((LottieValueCallback<Float>) callback);
400	      } else {
401	        blurAnimation =
402	            new ValueCallbackKeyframeAnimation<>((LottieValueCallback<Float>) callback);
403	        blurAnimation.addUpdateListener(this);
404	        layer.addAnimation(blurAnimation);
405	      }
406	    }
407	  }
