410	   * Data class to help drawing trim paths individually.
411	   */
412	  private static final class PathGroup {
413	    private final List<PathContent> paths = new ArrayList<>();
414	    @Nullable private final TrimPathContent trimPath;
415	
416	    private PathGroup(@Nullable TrimPathContent trimPath) {
417	      this.trimPath = trimPath;
418	    }
419	  }
