    isDirty = true;

    // Refer to invalidateSelfOnMainThread for more info.
    if (invalidateSelfOnMainThread && Looper.getMainLooper() != Looper.myLooper()) {
      return;
    }
    final Callback callback = getCallback();
    if (callback != null) {
      callback.invalidateDrawable(this);
    }
  }

